import assert from "node:assert/strict";
import { writeFile } from "node:fs/promises";
import { createServer } from "vite";
import { launchRenderBrowser } from "../packages/execution-runtime/src/render-browser.ts";

const server = await createServer({ root: process.cwd(), configFile: false,
  cacheDir: "/private/tmp/ce15-canvas-lifetime-native-vite", logLevel: "error",
  server: { host: "127.0.0.1", port: 0, watch: null } });
await server.listen();
const browser = await launchRenderBrowser();
try {
  const page = await browser.newPage();
  await page.addInitScript("window.__name=(fn)=>fn;");
  await page.goto(server.resolvedUrls!.local[0]!);
  const report = await page.evaluate(async () => {
    const root = "/packages/renderer-core/src/";
    const { ManagedMemory } = await import(root + "managed-memory.ts");
    const { withManagedMemory } = await import(root + "managed-memory-context.ts");
    const { colorEffectKernel } = await import(root + "composition/render/color-effects.ts");
    const check = (ok: unknown, message: string) => { if (!ok) throw Error(message); };
    const initial = [10,20,30,255,40,50,60,255,70,80,90,255,100,110,120,255];
    const expected = [128,128,128,255,128,128,127,255,128,128,128,255,128,128,128,255];
    const cases = [];
    for (const mode of ["consumer-dispose", "data-null", "buffer-null", "data-alias", "buffer-alias", "factory-dispose"]) {
      const memory = new ManagedMemory({pixels: 4194304, metadata: 2097152});
      const canvas = document.createElement("canvas"); canvas.width = canvas.height = 2;
      const ctx = canvas.getContext("2d")!;
      ctx.putImageData(new ImageData(new Uint8ClampedArray(initial),2,2),0,0);
      const outputCanvas = document.createElement("canvas"); outputCanvas.width = outputCanvas.height = 2;
      const outputCtx = outputCanvas.getContext("2d")!;
      const input = {width:2,height:2,canvas,ctx};
      const output = {width:2,height:2,canvas:outputCanvas,ctx:outputCtx};
      let backing: ArrayBuffer | undefined, originalGets = 0, consumerCalls = 0;
      const prior = memory.allocate("pixels",16,()=>new ArrayBuffer(16),true,(v: object)=>v,
        (v: ArrayBuffer)=>v.transfer(0));
      new Uint8Array(prior).fill(77);
      const nativeRead = ctx.getImageData.bind(ctx);
      ctx.getImageData = ((...args: Parameters<typeof nativeRead>) => {
        const image = nativeRead(...args), data = image.data;
        backing = data.buffer as ArrayBuffer;
        const key = mode.startsWith("data-") ? "data" : "buffer";
        if (mode.endsWith("-null") || mode.endsWith("-alias"))
          Object.defineProperty(key === "data" ? image : data,key,{get() {
            originalGets++;
            if (mode.endsWith("-null")) throw null;
            return key === "data" ? new Uint8ClampedArray(prior) : prior;
          }});
        if (mode === "factory-dispose") {
          memory.dispose(); check(memory.statistics.current.pixels === 16,"factory admission lost");
        }
        return image;
      }) as typeof ctx.getImageData;
      const nativePut = outputCtx.putImageData.bind(outputCtx);
      outputCtx.putImageData = ((...args: Parameters<typeof nativePut>) => {
        consumerCalls++;
        memory.dispose();
        check(memory.owns(backing),"consumer lost backing owner");
        check(backing!.byteLength === 16,"consumer detached backing");
        check(memory.statistics.current.pixels === 16,"consumer admission lost");
        nativePut(...args);
      }) as typeof outputCtx.putImageData;
      let failed = false, reason: unknown;
      await withManagedMemory(memory, async () => {
        const kernel = colorEffectKernel("color.invert")!;
        try { kernel.renderCanvas({createSurface:()=>output},input,{amount:0.5}); }
        catch (error) { failed = true; reason = error; }
      });
      if (mode === "consumer-dispose") {
        check(!failed,"native consumer failed");
        check(JSON.stringify([...outputCtx.getImageData(0,0,2,2).data]) === JSON.stringify(expected),"native pixels differ");
        check(consumerCalls === 1,"native consumer count");
      } else {
        check(failed,"failure not propagated"); check(consumerCalls === 0,"failed image committed");
        if (mode.endsWith("-null")) check(reason === null,"first null replaced");
        if (mode.endsWith("-alias")) {
          check(prior.byteLength === 16,"known alias destroyed");
          check([...new Uint8Array(prior)].every(v=>v===77),"known alias mutated");
        }
        if (mode !== "factory-dispose") check(originalGets === 1,"original Get repeated");
      }
      check(backing!.byteLength === 0,"fresh native backing leaked");
      memory.dispose();
      check(memory.statistics.current.pixels === 0 && memory.statistics.current.metadata === 0,"unsettled admission");
      cases.push({mode,originalGets,consumerCalls,detached:true,settled:true});
    }
    return {status:"passed",cases};
  });
  assert.equal(report.cases.length,6);
  await writeFile("/private/tmp/ce15-color-canvas-lifetime-native-results.json",JSON.stringify(report,null,2)+"\n");
  console.log(JSON.stringify(report));
} finally { await browser.close(); await server.close(); }
